//! Results of the managed runtime for the decimal members, the numeric
//! format strings and the parse styles the numeric controls use, and the
//! comparison of this implementation with them.
//!
//! The tables were generated with .NET 10.0.5 on macOS, where the managed runtime takes
//! its culture data from ICU. The cultures other than the invariant one come
//! from the culture data provider of the tests.

use super::number_format::format_decimal_composite;
use super::{CultureInfo, Decimal, NumberFormatInfo, NumberParseError, NumberStyles, TestCultureDataProvider};
use crate::FerroLocator;
use std::cmp::Ordering;
use std::rc::Rc;

/// The properties of a number format information, in the alphabetical
/// order of the managed type.
type InfoRow<'a> = (
    &'a str, i32, &'a str, &'a str, &'a [i32], i32, i32, &'a str, &'a str, &'a str, &'a str, i32, &'a str, &'a str,
    &'a [i32], i32, i32, &'a str, &'a str, &'a [i32], i32, i32, &'a str, &'a str, &'a str, &'a str,
);

#[rustfmt::skip]
const INFOS: &[InfoRow<'static>] = &[
    ("", 2, ".", ",", &[3], 0, 0, "\u{00A4}", "NaN", "-Infinity", "-", 2, ".", ",", &[3], 1, 2, ".", ",", &[3], 0, 0, "%", "\u{2030}", "Infinity", "+"),
    ("en", 2, ".", ",", &[3], 1, 0, "\u{00A4}", "NaN", "-\u{221E}", "-", 3, ".", ",", &[3], 1, 3, ".", ",", &[3], 1, 1, "%", "\u{2030}", "\u{221E}", "+"),
    ("en-US", 2, ".", ",", &[3], 1, 0, "$", "NaN", "-\u{221E}", "-", 3, ".", ",", &[3], 1, 3, ".", ",", &[3], 1, 1, "%", "\u{2030}", "\u{221E}", "+"),
    ("en-GB", 2, ".", ",", &[3], 1, 0, "\u{00A3}", "NaN", "-\u{221E}", "-", 3, ".", ",", &[3], 1, 3, ".", ",", &[3], 1, 1, "%", "\u{2030}", "\u{221E}", "+"),
];

