fn d(text: &str) -> Decimal {
    Decimal::parse(text).unwrap()
}

/// Runs  with the culture data provider of the tests registered.
fn with_cultures(test: impl FnOnce()) {
    let scope = FerroLocator::enter_scope();
    TestCultureDataProvider::register();
    test();
    scope.dispose();
}

fn info(culture: &str) -> Rc<NumberFormatInfo> {
    CultureInfo::get_culture_info(culture).number_format()
}

/// The fields of a row as text (a tuple of this size has no debug form).
fn fields(row: &InfoRow<'_>) -> Vec<String> {
    vec![
        format!("{:?}", row.0),
        format!("{:?}", row.1),
        format!("{:?}", row.2),
        format!("{:?}", row.3),
        format!("{:?}", row.4),
        format!("{:?}", row.5),
        format!("{:?}", row.6),
        format!("{:?}", row.7),
        format!("{:?}", row.8),
        format!("{:?}", row.9),
        format!("{:?}", row.10),
        format!("{:?}", row.11),
        format!("{:?}", row.12),
        format!("{:?}", row.13),
        format!("{:?}", row.14),
        format!("{:?}", row.15),
        format!("{:?}", row.16),
        format!("{:?}", row.17),
        format!("{:?}", row.18),
        format!("{:?}", row.19),
        format!("{:?}", row.20),
        format!("{:?}", row.21),
        format!("{:?}", row.22),
        format!("{:?}", row.23),
        format!("{:?}", row.24),
        format!("{:?}", row.25),
    ]
}

#[test]
fn number_format_infos_match() {
    with_cultures(|| {
        for row in INFOS {
            let info = info(row.0);
            let actual: InfoRow<'_> = (
                row.0,
                info.currency_decimal_digits(),
                info.currency_decimal_separator(),
                info.currency_group_separator(),
                info.currency_group_sizes(),
                info.currency_negative_pattern(),
                info.currency_positive_pattern(),
                info.currency_symbol(),
                info.nan_symbol(),
                info.negative_infinity_symbol(),
                info.negative_sign(),
                info.number_decimal_digits(),
                info.number_decimal_separator(),
                info.number_group_separator(),
                info.number_group_sizes(),
                info.number_negative_pattern(),
                info.percent_decimal_digits(),
                info.percent_decimal_separator(),
                info.percent_group_separator(),
                info.percent_group_sizes(),
                info.percent_negative_pattern(),
                info.percent_positive_pattern(),
                info.percent_symbol(),
                info.per_mille_symbol(),
                info.positive_infinity_symbol(),
                info.positive_sign(),
            );
            assert_eq!(fields(&actual), fields(row), "{:?}", row.0);
        }
    });
}

#[test]
fn arithmetic_matches() {
    for &(left, right, sum, difference, quotient, order) in ARITHMETIC {
        let (a, b) = (d(left), d(right));
        let text = |value: Option<Decimal>| value.map(|value| value.to_string());
        assert_eq!(text(a.checked_add(b)).as_deref(), sum, "{left} + {right}");
        assert_eq!(text(a.checked_sub(b)).as_deref(), difference, "{left} - {right}");
        if !b.is_zero() {
            assert_eq!(text(a.checked_div(b)).as_deref(), quotient, "{left} / {right}");
        }
        let expected = match order {
            0 => Ordering::Equal,
            1 => Ordering::Greater,
            _ => Ordering::Less,
        };
        assert_eq!(a.cmp(&b), expected, "{left} <=> {right}");
        assert_eq!(a == b, order == 0, "{left} == {right}");
        assert_eq!(a.max(b), if order < 0 { b } else { a }, "max({left}, {right})");
        assert_eq!(a.min(b), if order > 0 { b } else { a }, "min({left}, {right})");
    }
}

#[test]
fn formatting_matches() {
    with_cultures(|| {
        for &(culture, value, format, expected) in FORMATS {
            let actual = d(value).to_string_with(format, Some(&info(culture))).ok();
            assert_eq!(actual.as_deref(), expected, "{value} with {format:?} in {culture:?}");
        }
    });
}

#[test]
fn composite_formatting_matches() {
    with_cultures(|| {
        for &(culture, value, format, expected) in COMPOSITES {
            let actual = format_decimal_composite(format, &info(culture), value.map(d)).ok();
            assert_eq!(actual.as_deref(), expected, "{value:?} with {format:?} in {culture:?}");
        }
    });
}

#[test]
fn parsing_matches() {
    with_cultures(|| {
        for &(culture, styles, text, expected) in PARSES {
            let actual = Decimal::parse_with(text, styles, Some(&info(culture))).map(|value| {
                if value.is_zero() && value.is_sign_negative() {
                    format!("-{value}")
                } else {
                    value.to_string()
                }
            });
            assert_eq!(actual.as_deref().map_err(|error| *error), expected, "{text:?} with {styles:?} in {culture:?}");
        }
    });
}
